// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        Reverter reverter = new Reverter();
        vm.deal(address(c), 2 ether);
        vm.deal(address(reverter), 0);
        amount = bound(amount, 1, address(c).balance);

        vm.prank(c.owner());
        bool ok; try c.withdraw(amount) { ok = true; } catch { ok = false; }

        assertTrue(!ok || address(reverter).balance > 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}
